def won(n):
    return f"{n:,}원"


def eun_neun(word):
    """Pick the Korean topic particle 은/는 by final-consonant of the last char."""
    last = word[-1]
    if "가" <= last <= "힣":
        return "은" if (ord(last) - 0xAC00) % 28 else "는"
    return "는"


def eseo(word):
    """에서 is invariant; helper kept for readability in templates."""
    return "에서"


