   "이때 집에서 받는 방문 케어를 더하면, 외출 없이 굳은 어깨·허리를 정리하고 그대로 휴식으로 이어 갈 수 있습니다. 가족이 함께 사는 집이라면 서로의 일정이 겹치지 않는 시간대를 골라 차분한 분위기를 만들면 좋습니다.",
   "## 예약 시 참고하세요",
