def with_extra(slug, body):
    """Insert the slug's extra sections just before the body's closing paragraph."""
    extra = (ARTICLE_EXTRA.get(slug, []) + ARTICLE_EXTRA2.get(slug, [])
             + ARTICLE_EXTRA3.get(slug, []) + ARTICLE_EXTRA4.get(slug, [])
             + ARTICLE_EXTRA5.get(slug, []) + ARTICLE_EXTRA6.get(slug, [])
             + ARTICLE_EXTRA7.get(slug, []))
    if not extra:
        return body
    return body[:-1] + extra + [body[-1]]


