# ---------------------------------------------------------------------------
# HTML scaffold
# ---------------------------------------------------------------------------
def page(path, title, description, body, jsonld=None, image=None, og_type="website"):
    """path is like 'areas/suwon.html' (relative to repo root)."""
    canonical = BASE + "/" + path.replace("index.html", "")
    image = image or OG_IMAGE
    jl = ""
    for block in (jsonld or []):
        jl += '\n  <script type="application/ld+json">' + block + "</script>"
    doc = f"""<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{html.escape(title)}</title>
  <meta name="description" content="{html.escape(description)}">
  <link rel="canonical" href="{canonical}">
  <meta property="og:type" content="{og_type}">
  <meta property="og:title" content="{html.escape(title)}">
  <meta property="og:description" content="{html.escape(description)}">
  <meta property="og:locale" content="ko_KR">
  <meta property="og:url" content="{canonical}">
  <meta property="og:image" content="{image}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:image" content="{image}">
  <meta name="theme-color" content="#0c1016">
  <link rel="icon" type="image/svg+xml" href="/favicon.svg">
  <link rel="apple-touch-icon" href="/favicon.svg">
  <link rel="preconnect" href="https://cdn.jsdelivr.net" crossorigin>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css">
  <link rel="stylesheet" href="/assets/css/styles.css">{jl}
</head>
<body>
  <div id="site-header"></div>
{body}
  <div id="site-footer"></div>
  <script src="/assets/js/site.js"></script>
</body>
</html>
"""
    full = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "w", encoding="utf-8") as f:
        f.write(doc)


def render_prose(items):
    """Render a list of paragraphs; '## ' prefix => <h3> heading in prose."""
    out = []
    for it in items:
        if it.startswith("## "):
            out.append(f"<h3>{html.escape(it[3:])}</h3>")
        else:
            out.append(f"<p>{html.escape(it)}</p>")
    return "\n        ".join(out)


def breadcrumb_ld(items):
    el = []
    for i, (name, url) in enumerate(items, 1):
        el.append('{"@type":"ListItem","position":%d,"name":"%s","item":"%s"}'
                   % (i, name, BASE + url))
    return '{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[' + ",".join(el) + "]}"


def crumb_html(items):
    parts = []
    for i, (name, url) in enumerate(items):
        if i < len(items) - 1:
            parts.append(f'<a href="{url}">{html.escape(name)}</a><span class="sep">›</span>')
        else:
            parts.append(f'<span aria-current="page">{html.escape(name)}</span>')
    return '<nav class="breadcrumb" aria-label="현재 위치">' + "".join(parts) + "</nav>"


def nearby_areas(a):
    return [x for x in AREAS if x["region"] == a["region"] and x["slug"] != a["slug"]]


def area_links_for_region(region, exclude=None):
    out = []
    for a in AREAS:
        if a["region"] == region and a["slug"] != exclude:
            out.append(f'<a href="/areas/{a["slug"]}.html">{a["ko"]} 출장마사지</a>')
    return "".join(out)


